var payload = msg.payload;
var topic = msg.topic;
var parts = topic.split('/');
var chambre_id = parts[1] || 'INCONNU';

// Extraction des valeurs
var fc = payload.frequence_cardiaque;
var temp = payload.temperature;
var syst = payload.pression_systolique;
var diast = payload.pression_diastolique;
var co2 = payload.co2_ppm;

var alertes = [];

// ── Fréquence cardiaque ──
if (fc !== undefined) {
    if (fc < 40 || fc > 150) {
        alertes.push({ niveau: 'ROUGE', field: 'frequence_cardiaque', valeur: fc, unite: 'bpm',
            message: 'FC critique : ' + fc + ' bpm (normale 60-100)' });
    } else if (fc < 50 || fc > 120) {
        alertes.push({ niveau: 'ORANGE', field: 'frequence_cardiaque', valeur: fc, unite: 'bpm',
            message: 'FC anormale : ' + fc + ' bpm' });
    }
}

// ── Température ──
if (temp !== undefined) {
    if (temp > 40 || temp < 34) {
        alertes.push({ niveau: 'ROUGE', field: 'temperature', valeur: temp, unite: '°C',
            message: 'Température critique : ' + temp + '°C' });
    } else if (temp > 38.5 || temp < 36) {
        alertes.push({ niveau: 'ORANGE', field: 'temperature', valeur: temp, unite: '°C',
            message: 'Température anormale : ' + temp + '°C' });
    }
}

// ── Pression artérielle systolique ──
if (syst !== undefined) {
    if (syst > 180 || syst < 70) {
        alertes.push({ niveau: 'ROUGE', field: 'pression_systolique', valeur: syst, unite: 'mmHg',
            message: 'Pression systolique critique : ' + syst + ' mmHg' });
    } else if (syst > 140 || syst < 90) {
        alertes.push({ niveau: 'ORANGE', field: 'pression_systolique', valeur: syst, unite: 'mmHg',
            message: 'Pression systolique anormale : ' + syst + ' mmHg' });
    }
}

// ── CO2 ──
if (co2 !== undefined) {
    if (co2 > 2000) {
        alertes.push({ niveau: 'ROUGE', field: 'co2_ppm', valeur: co2, unite: 'ppm',
            message: 'CO₂ dangereux : ' + co2 + ' ppm (max 1000)' });
    } else if (co2 > 1000) {
        alertes.push({ niveau: 'ORANGE', field: 'co2_ppm', valeur: co2, unite: 'ppm',
            message: 'CO₂ élevé : ' + co2 + ' ppm' });
    }
}

var messages = [];
alertes.forEach(function(a) {
    messages.push({
        payload: {
            chambre_id: chambre_id,
            type_alerte: 'vitaux',
            niveau: a.niveau,
            message: a.message,
            valeur_capteur: a.valeur,
            unite: a.unite,
            source: 'node-red/vitaux'
        }
    });
});

return [messages];

var payload = msg.payload;
var topic = msg.topic;
var parts = topic.split('/');
var zone = parts[2] || 'zone_inconnue';

var alertes = [];

if (payload.intrusion === true || payload.mouvement_non_autorise === true) {
    alertes.push({
        chambre_id: zone,
        type_alerte: 'intrusion',
        niveau: 'ROUGE',
        message: 'Intrusion détectée dans la zone : ' + zone,
        valeur_capteur: null,
        unite: null,
        source: 'node-red/securite'
    });
}

if (payload.porte_forcee === true) {
    alertes.push({
        chambre_id: zone,
        type_alerte: 'intrusion',
        niveau: 'ROUGE',
        message: 'Porte forcée — zone : ' + zone,
        valeur_capteur: null,
        unite: null,
        source: 'node-red/securite'
    });
}

if (payload.acces_non_autorise === true) {
    alertes.push({
        chambre_id: zone,
        type_alerte: 'intrusion',
        niveau: 'ORANGE',
        message: 'Tentative d\'accès non autorisé — zone : ' + zone,
        valeur_capteur: null,
        unite: null,
        source: 'node-red/securite'
    });
}

var messages = alertes.map(function(a) { return { payload: a }; });
return [messages];

var payload = msg.payload;
var zone = payload.zone || 'batiment';
var tension = payload.tension_v;
var mode = payload.mode_alimentation;
var conso = payload.consommation_kw;

var alertes = [];

if (mode === 'groupe_electrogene' || mode === 'onduleur') {
    alertes.push({
        chambre_id: zone,
        type_alerte: 'energie',
        niveau: 'ORANGE',
        message: 'Alimentation de secours active : ' + mode,
        valeur_capteur: null,
        unite: null,
        source: 'node-red/energie'
    });
}

if (mode === 'panne' || tension < 180) {
    alertes.push({
        chambre_id: zone,
        type_alerte: 'energie',
        niveau: 'ROUGE',
        message: 'PANNE ÉLECTRIQUE — tension : ' + tension + 'V',
        valeur_capteur: tension,
        unite: 'V',
        source: 'node-red/energie'
    });
}

if (conso > 50) {
    alertes.push({
        chambre_id: zone,
        type_alerte: 'energie',
        niveau: 'ORANGE',
        message: 'Consommation anormalement élevée : ' + conso + ' kW',
        valeur_capteur: conso,
        unite: 'kW',
        source: 'node-red/energie'
    });
}

var messages = alertes.map(function(a) { return { payload: a }; });
return [messages];

var payload = msg.payload;
var topic = msg.topic;
var chambre_id = topic.split('/')[1] || 'INCONNU';

if (payload.appel === true || payload.bouton_presse === true) {
    return [{
        payload: {
            chambre_id: chambre_id,
            type_alerte: 'appel',
            niveau: 'ROUGE',
            message: 'APPEL PATIENT — chambre ' + chambre_id + ' : assistance requise',
            valeur_capteur: null,
            unite: null,
            source: 'node-red/appel'
        }
    }];
}
return null;

// Évite de renvoyer la même alerte plusieurs fois en 30 secondes
var key = msg.payload.chambre_id + ':' + msg.payload.type_alerte + ':' + msg.payload.niveau;
var now = Date.now();
var cache = context.get('alerte_cache') || {};

if (cache[key] && (now - cache[key]) < 30000) {
    return null; // doublon, on ignore
}

cache[key] = now;
context.set('alerte_cache', cache);
return msg;

msg.headers = msg.headers || {};
msg.headers['Authorization'] = 'Bearer ' + env.get('NODERED_API_TOKEN');
msg.headers['Content-Type'] = 'application/json';
return msg;
